    @Override
    public void reset() {
        mGameWorld.getBox2DWorld().destroyBody(mBody);
        mBody = null;
    }

    @Override
    public void dispose() {
        sPool.free(this);
    }

    @Override
    public void act(float delta) {}

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (zLevel != ZLevel.GROUND) {
            return;
        }
        float radius = mBody.getFixtureList().get(0).getShape().getRadius();
        if (!AgcMathUtils.rectangleContains(viewBounds, getPosition(), radius)) {
            return;
        }
        mDrawer.setBatch(batch);
        mDrawer.draw(mBody, mAssets.bullet);
    }

    @Override
    public void audioRender(AudioClipper clipper) {
        if (mJustShot) {
            mAudioManager.play(mAssets.soundAtlas.get("shoot"), clipper.clip(this));
            mJustShot = false;
        }
    }

    @Override
    public float getX() {
        return mBody.getPosition().x;
    }

    @Override
    public float getY() {
        return mBody.getPosition().y;
    }

    private void explode() {
        Vector2 pos = mBody.getPosition();
        AnimationObject obj = AnimationObject.create(mAssets.impact, pos.x, pos.y);
        obj.initAudio(mAudioManager, mAssets.soundAtlas.get("impact"));
        mGameWorld.addGameObject(obj);
        setFinished(true);
    }

    @Override
    public void beginContact(Contact contact, Fixture otherFixture) {}

    @Override
    public void endContact(Contact contact, Fixture otherFixture) {}

    @Override
    public void preSolve(Contact contact, Fixture otherFixture, Manifold oldManifold) {
        if (isFinished()) {
            return;
        }
        Object other = otherFixture.getBody().getUserData();
        if (other == mShooter) {
            contact.setEnabled(false);
            return;
        }

        explode();
        if (other instanceof Racer) {
            ((Racer) other).spin();
        } else if (other instanceof Explosable) {
            ((Explosable) other).explode();
        }
    }

    @Override
    public void postSolve(Contact contact, Fixture otherFixture, ContactImpulse impulse) {}
}
    @Override
    public void dispose() {
        sPool.free(this);
    }

    @Override
    public void act(float delta) {
        mTime += delta;
    }

    private final BodyRegionDrawer mBodyRegionDrawer = new BodyRegionDrawer();

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        mBodyRegionDrawer.setBatch(batch);

        Material material = mGameWorld.getTrack().getMaterialAt(getPosition());
        boolean hasBeenDropped = mJoint == null;
        boolean drawShadow = !hasBeenDropped || !material.isWater();
        if (hasBeenDropped) {
            switch (material) {
                case WATER:
                    batch.setColor(Constants.HALF_IMMERSED_COLOR);
                    break;
                case DEEP_WATER:
                    batch.setColor(Constants.FULLY_IMMERSED_COLOR);
                    break;
                default:
                    break;
            }
        } else {
            batch.setColor(mOwner.getVehicleRenderer().getBatchColor());
        }

        if (zLevel == ZLevel.GROUND && drawShadow) {
            // Smaller shadow if the mine has been dropped
            float z = hasBeenDropped ? -0.1f : 0f;
            mBodyRegionDrawer.setZ(z);
            TextureRegion region = mAssets.mine.getKeyFrame(mTime);
            mBodyRegionDrawer.drawShadow(mBody, region);
        }
        if (zLevel == ZLevel.VEHICLES) {
            TextureRegion region = mAssets.mine.getKeyFrame(mTime);
            mBodyRegionDrawer.draw(mBody, region);
        }

        batch.setColor(Color.WHITE);
    }

    @Override
    public float getX() {
    private void actLocked(float delta) {
        mGuidingSystem.act(mTarget.getPosition());
        consumeTime(delta);
    }

    private void consumeTime(float delta) {
        mTime += delta;
        if (mTime >= DURATION) {
            explode();
        }
    }

    private void findTarget() {
        World world = mGameWorld.getBox2DWorld();
        mTarget =
                mRacerFinder.find(
                        world, mBody.getWorldCenter(), mBody.getAngle() * MathUtils.radDeg);
    }

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (zLevel == ZLevel.FLYING) {
            // Draw the shadow at Z_FLYING so that the shadow is drawn *over* its vehicle
            drawShadow(batch);
            drawMissile(batch);
            drawTarget(batch);
            if (mStatus != Status.WAITING) {
                drawReactorFire(batch);
            }
        }
    }

    private void drawTarget(Batch batch) {
        if (mTarget == null) {
            return;
        }
        batch.setColor(mStatus == Status.LOCKED ? LOCKED_COLOR : TARGETED_COLOR);
        TextureRegion region = mAssets.target;
        float w = Constants.UNIT_FOR_PIXEL * region.getRegionWidth();
        float h = Constants.UNIT_FOR_PIXEL * region.getRegionHeight();
        batch.draw(region, mTarget.getX() - w / 2, mTarget.getY() - h / 2, w, h);
        batch.setColor(Color.WHITE);
    }

    private void drawMissile(Batch batch) {
        mDrawer.setBatch(batch);
        mDrawer.draw(mBody, mAssets.missile);
    }

    private void drawReactorFire(Batch batch) {
        TextureRegion region = mAssets.turboFlame.getKeyFrame(mTime, true);
        Vector2 center = mBody.getPosition();
        float angle = mBody.getAngle();
        float w = Constants.UNIT_FOR_PIXEL * region.getRegionWidth();
        float h = Constants.UNIT_FOR_PIXEL * region.getRegionHeight();
        float refH = Constants.UNIT_FOR_PIXEL * -WIDTH / 2;
        mReactorPos.set(0, refH).rotateRad(angle).add(center);
        float x = mReactorPos.x;
        float y = mReactorPos.y;
        batch.draw(
                region,
                x - w / 2,
                y - h, // pos
                w / 2,
                h, // origin
                w,
                h, // size
                1,
                1, // scale
                angle * MathUtils.radDeg - 90);
    }

    private void drawShadow(Batch batch) {
        mDrawer.setBatch(batch);
        mDrawer.drawShadow(mBody, mAssets.missile);
    }

    @Override
    public void audioRender(AudioClipper clipper) {
        if (mNeedShootSound) {
            mSoundPlayer = mAudioManager.createSoundPlayer(mAssets.soundAtlas.get("missile"));
            mSoundPlayer.setVolume(clipper.clip(this));
            mSoundPlayer.play();

            mNeedShootSound = false;
        }
    }

    @Override
    public float getX() {
        return mBody.getPosition().x;
/** A turbo bonus */
public class TurboBonus extends BonusAdapter implements Pool.Poolable {
    private boolean mTriggered = false;
    private float mAnimationTime;

    private final Renderer mBonusRenderer =
            new Renderer() {
                @Override
                public void draw(Batch batch, float centerX, float centerY) {
                    TextureRegion region = mAssets.turbo.getKeyFrame(mAnimationTime, true);
                    Vehicle vehicle = mRacer.getVehicle();
                    Body body = vehicle.getBody();
                    float angle = body.getAngle() * MathUtils.radiansToDegrees;
                    float w = region.getRegionWidth();
                    float h = region.getRegionHeight();
                    float refH = -vehicle.getRegion(0).getRegionWidth() / 3f;
                    float x = centerX + refH * MathUtils.cosDeg(angle);
                    float y = centerY + refH * MathUtils.sinDeg(angle);
                    batch.draw(
                            region,
                            x - w / 2,
                            y - h / 2, // pos
                            w / 2,
                            h / 2, // origin
                            w,
                            h, // size
                            1,
                            1, // scale
                            angle - 90);
                }
            };

    public TurboBonus() {
        reset();
    }

    @Override
    public void reset() {
        mAnimationTime = 0;
        mTriggered = false;
    }

    @Override
    public void onPicked(Racer racer) {
        super.onPicked(racer);
        mRacer.getVehicleRenderer().addRenderer(mBonusRenderer);
    }

    @Override
    public void onOwnerHit() {
        resetBonus();

    private final ClosestRacerFinder mClosestRacerFinder =
