                            w / 2,
                            h / 2, // origin
                            w,
                            h, // size
                            1,
                            1, // scale
                            angle - 90);
                }
            };

    private final Vector2 mRayCastOrigin = new Vector2();

    private final DebugShapeMap.Shape mDebugShape =
            renderer -> {
                float angle = mRacer.getVehicle().getAngle();
                renderer.begin(ShapeRenderer.ShapeType.Line);
                renderer.setColor(1, 0, 0, 1);
                renderer.line(
    @Override
